input.command:
SCRATCH=$(mktemp -d /tmp/spec-refresh.XXXXXX) && echo "$SCRATCH" > /tmp/spec-refresh-scratch-path && cat > "$SCRATCH/build-candidates.cjs" <<'EOF'
const fs = require('fs');
const [,, repo, scratch] = process.argv;
const read = p => fs.readFileSync(p);
const oldBytes = read(`${repo}/docs/solutions/old.md`);
const newBytes = read(`${repo}/docs/solutions/new.md`);
const catBytes = read(`${repo}/docs/solutions/catalog.md`);

// 1. private recovery copy of the original (verbatim bytes)
fs.writeFileSync(`${scratch}/old.md.recovery`, oldBytes);

// 2. new.md candidate = exact current bytes + one blank line + verbatim offline section to EOF
const marker = Buffer.from('## 离线恢复');
const hits = [];
for (let i = 0; (i = oldBytes.indexOf(marker, i)) !== -1; i += marker.length) hits.push(i);
if (hits.length !== 1) throw new Error(`marker count ${hits.length}`);
const section = oldBytes.slice(hits[0]);
const expected = Buffer.from('## 离线恢复\n\n离线时保留最后可用凭据，不删除备份。\n');
if (!section.equals(expected)) throw new Error('section bytes mismatch vs expectation');
const newCand = Buffer.concat([newBytes, Buffer.from('\n'), section]);
fs.writeFileSync(`${scratch}/new.md.candidate`, newCand);

// 3. catalog candidate = single citation rewrite, every other byte preserved
const needle = 'old.md#离线恢复';
const catStr = catBytes.toString('utf8');
const n = catStr.split(needle).length - 1;
if (n !== 1) throw new Error(`citation count ${n}`);
const catCand = Buffer.from(catStr.replace(needle, 'new.md#离线恢复'));
fs.writeFileSync(`${scratch}/catalog.md.candidate`, catCand);

console.log(JSON.stringify({
  prefixPreserved: newCand.slice(0, newBytes.length).equals(newBytes),
  blankLineAdded: newCand[newBytes.length] === 0x0a,
  sectionVerbatimWithFinalNewline: section.equals(expected),
  catalogBytesElsewherePreserved: catCand.equals(Buffer.from(catStr.replace(needle, 'new.md#离线恢复'))),
  userEntryPreserved: catCand.toString('utf8').includes('用户新增条目：值班交接时核对最后一次备份时间。'),
  newCandidateSHA256: '(next step)',
}, null, 2));
EOF
node "$SCRATCH/build-candidates.cjs" "$(pwd)" "$SCRATCH"
